  base jsonb; c jsonb; o jsonb; x jsonb; p text[]; hasil text[]; harapan text[]; n int := 0; d text;
begin
  base := vek -> 'base';
  select pg_get_functiondef(pr.oid) into d from pg_proc pr where pr.proname = 'keu_lanjutan_periksa' and pr.pronamespace = 'public'::regnamespace;
  if position('instruktur' in d) = 0 then raise exception 'GAGAL: pemeriksa belum ditambal (jalankan 20261028e)'; end if;
  for c in select value from jsonb_array_elements(vek -> 'cases') loop
    x := base;
    for o in select value from jsonb_array_elements(c -> 'ops') loop
      p := array(select jsonb_array_elements_text(o -> 'path'));
      if o ->> 'op' = 'set' then x := jsonb_set(x, p, o -> 'value', true);
      elsif o ->> 'op' = 'del' then x := x #- p;
      elsif o ->> 'op' = 'tambah' then x := jsonb_set(x, p, (x #> p) || jsonb_build_array(o -> 'value'));
      elsif o ->> 'op' = 'ganti' then x := o -> 'value';
      end if;
    end loop;
    hasil := array(select e from unnest(keu_lanjutan_periksa(x)) e order by e);
    harapan := array(select jsonb_array_elements_text(c -> 'galat') order by 1);
    if hasil is distinct from harapan then raise exception 'GAGAL: kasus "%": SQL %, harapan %', c ->> 'nama', hasil, harapan; end if;
    if cardinality(harapan) = 0 and c ? 'status' and keu_lanjutan_status(x) is distinct from (c ->> 'status') then
      raise exception 'GAGAL: status kasus "%": SQL %, harapan %', c ->> 'nama', keu_lanjutan_status(x), c ->> 'status';
    end if;
    n := n + 1;
  end loop;
  if n <> 91 then raise exception 'GAGAL: seharusnya 91 kasus, dijalankan %', n; end if;
  raise notice 'LULUS 72 (% kasus)', n;
end $$;
rollback;
